// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint64 newTimestamp) public {
        vm.assume(actor != address(0));
        vm.assume(newTimestamp > 0);

        vm.deal(actor, 20 ether);

        uint256 before = c.pastBlockTime();

        uint64 target = newTimestamp;
        if (target <= uint64(before)) {
            unchecked { target = uint64(before) + 1; }
        }

        vm.warp(uint256(target));

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("\x00");

        if (ok) {
            assertTrue(c.pastBlockTime() == uint256(target));
        } else {
            assertTrue(c.pastBlockTime() <= uint256(target));
        }
    }
}
